'use client';
import React, { useState } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';
import { ThemeProvider, CssBaseline } from '@mui/material';
import { theme } from '@/lib/theme';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 2,
      staleTime: 1000 * 30, // 30s SWR
    },
  },
});

export function Providers({ children }: { children: React.ReactNode }) {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider theme={theme}>
        <CssBaseline />
        {children}
        {process.env.NODE_ENV === 'development' && <ReactQueryDevtools />}
      </ThemeProvider>
    </QueryClientProvider>
  );
}

'use client';
import React, { useState, useCallback } from 'react';
import {
  Box, Button, CircularProgress, Container, Fab,
  Grid, Typography, Collapse, Alert,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import { Bottle } from '@/lib/bottles/types';
import {
  useBottles,
  useCreateBottle,
  useUpdateBottle,
  useDeleteBottle,
  useRestoreBottle,
} from '@/hooks/useBottles';
import { BottleCard, BottleCardSkeleton } from './BottleCard';
import { BottleForm } from './BottleForm';
import { UndoToast } from '@/components/ui/UndoToast';
import { useLogout, useMe } from '@/hooks/useAuth';
import LogoutIcon from '@mui/icons-material/Logout';

type UIMode = 'idle' | 'creating' | 'editing';

interface BottleDashboardProps {
  t: (key: string) => string;
}

/**
 * Page principale du CRUD bouteilles.
 * G├¿re : liste, cr├®ation, ├®dition, suppression avec Undo, Optimistic UI.
 */
export function BottleDashboard({ t }: BottleDashboardProps) {
  const { data: bottles, isLoading, isError, isFetching } = useBottles();
  const createMutation = useCreateBottle();
  const updateMutation = useUpdateBottle();
  const deleteMutation = useDeleteBottle();
  const restoreMutation = useRestoreBottle();

  const [mode, setMode] = useState<UIMode>('idle');
  const [editingBottle, setEditingBottle] = useState<Bottle | null>(null);

  const { data: user } = useMe();
  const logoutMutation = useLogout();

  // Undo toast state
  const [undoTarget, setUndoTarget] = useState<Bottle | null>(null);

  const handleCreate = useCallback(
    (values: Partial<Bottle>) => {
      createMutation.mutate(values as Bottle, {
        onSettled: () => setMode('idle'),
      });
      setMode('idle');
    },
    [createMutation]
  );

  const handleUpdate = useCallback(
    (values: Partial<Bottle>) => {
      if (!editingBottle) return;
      updateMutation.mutate(
        { id: editingBottle.id, patch: values },
        { onSettled: () => { setMode('idle'); setEditingBottle(null); } }
      );
    },
    [editingBottle, updateMutation]
  );

  const handleDelete = useCallback(
    (bottle: Bottle) => {
      deleteMutation.mutate(bottle.id, {
        onSuccess: () => setUndoTarget(bottle),
      });
    },
    [deleteMutation]
  );

  const handleUndo = useCallback(() => {
    if (!undoTarget) return;
    restoreMutation.mutate(undoTarget.id);
    setUndoTarget(null);
  }, [undoTarget, restoreMutation]);

  const handleEdit = useCallback((bottle: Bottle) => {
    setEditingBottle(bottle);
    setMode('editing');
  }, []);

  const handleCancel = useCallback(() => {
    setMode('idle');
    setEditingBottle(null);
  }, []);

  const categoryLabel = (cat: string) => t(`common.categories.${cat}`);

  return (
    <Container maxWidth="lg" sx={{ py: 3 }}>
      {/* Header */}
      <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Box>
          <Typography variant="h4" fontWeight={700}>
            {t('common.nav.bottles')}
          </Typography>
          {isFetching && !isLoading ? (
            <Typography variant="caption" color="text.secondary">
              {t('common.status.loading')}
            </Typography>
          ) : (
            <Typography variant="body2" color="text.secondary">
              Logged in as {user?.displayName ?? user?.username}
            </Typography>
          )}
        </Box>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <Button
            variant="outlined"
            color="inherit"
            startIcon={<LogoutIcon />}
            onClick={() => logoutMutation.mutate()}
            disabled={logoutMutation.isPending}
            sx={{ display: { xs: 'none', sm: 'flex' } }}
          >
            {t('common.auth.logout')}
          </Button>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setMode('creating')}
            sx={{ display: { xs: 'none', sm: 'flex' } }}
            aria-label={t('common.bottle.add')}
          >
            {t('common.bottle.add')}
          </Button>
        </Box>
      </Box>

      {/* Error state */}
      {isError && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {t('common.status.error')}
        </Alert>
      )}

      {/* Form panel */}
      <Collapse in={mode !== 'idle'} unmountOnExit>
        <Box sx={{ mb: 3 }}>
          <BottleForm
            initialValues={mode === 'editing' && editingBottle ? editingBottle : undefined}
            onSubmit={mode === 'creating' ? handleCreate : handleUpdate}
            onCancel={handleCancel}
            isSubmitting={createMutation.isPending || updateMutation.isPending}
            t={t}
          />
        </Box>
      </Collapse>

      {/* Loading skeletons */}
      {isLoading && (
        <Grid container spacing={2}>
          {Array.from({ length: 6 }).map((_, i) => (
            <Grid item xs={12} sm={6} md={4} key={i}>
              <BottleCardSkeleton />
            </Grid>
          ))}
        </Grid>
      )}

      {/* Empty state */}
      {!isLoading && !isError && bottles?.length === 0 && mode === 'idle' && (
        <Box
          sx={{
            textAlign: 'center',
            py: 8,
            border: '2px dashed',
            borderColor: 'divider',
            borderRadius: 2,
            bgcolor: 'action.hover',
          }}
        >
          <Typography variant="h6" color="text.secondary" gutterBottom>
            {t('common.bottle.noBottles')}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            {t('common.bottle.noBottlesDesc')}
          </Typography>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setMode('creating')}
          >
            {t('common.bottle.add')}
          </Button>
        </Box>
      )}

      {/* Bottle grid */}
      {!isLoading && bottles && bottles.length > 0 && (
        <Grid container spacing={2}>
          {bottles.map((bottle) => (
            <Grid item xs={12} sm={6} md={4} key={bottle.id}>
              <BottleCard
                bottle={bottle}
                categoryLabel={categoryLabel(bottle.category)}
                onEdit={handleEdit}
                onDelete={handleDelete}
                t={t}
              />
            </Grid>
          ))}
        </Grid>
      )}

      {/* FAB for mobile */}
      <Fab
        color="primary"
        aria-label={t('common.bottle.add')}
        sx={{ position: 'fixed', bottom: 80, right: 24, display: { sm: 'none' } }}
        onClick={() => setMode('creating')}
      >
        <AddIcon />
      </Fab>

      {/* Undo toast (soft delete) */}
      {undoTarget && (
        <UndoToast
          message={t('common.toast.deleteSuccess')}
          undoLabel={t('common.actions.undo')}
          onUndo={handleUndo}
          onExpire={() => setUndoTarget(null)}
        />
      )}
    </Container>
  );
}

'use client';
import React, { useState } from 'react';
import {
  Box, Button, Collapse, Divider, FormControl, Grid,
  IconButton, InputLabel, MenuItem, Paper, Select,
  TextField, Tooltip, Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import SaveIcon from '@mui/icons-material/Save';
import { Bottle, BottleCategory } from '@/lib/bottles/types';
import { CategoryFields, OptionalFields } from './CategoryFields';

interface BottleFormProps {
  initialValues?: Partial<Bottle>;
  onSubmit: (values: Partial<Bottle>) => void;
  onCancel: () => void;
  isSubmitting?: boolean;
  t: (key: string) => string;
}

const EMPTY_FORM: Partial<Bottle> = {
  category: 'wine',
  name: '',
  producer: '',
  tags: [],
  grapeVarieties: [],
  isOpened: false,
  alertStatus: 'none',
};

/**
 * Formulaire 2 temps :
 * 1) Tronc commun (cat├®gorie + nom + producteur) ÔåÆ sauvegarde possible d├¿s ici
 * 2) Champs essentiels par cat├®gorie + section optionnelle repliable
 */
export function BottleForm({ initialValues, onSubmit, onCancel, isSubmitting = false, t }: BottleFormProps) {
  const [values, setValues] = useState<Partial<Bottle>>(initialValues ?? EMPTY_FORM);
  const [showOptionals, setShowOptionals] = useState(false);
  const [step, setStep] = useState<1 | 2>(1);

  const setField = (field: string, value: unknown) => {
    setValues((prev) => ({ ...prev, [field]: value }));
  };

  const canSaveMinimal = Boolean(values.category && values.name?.trim() && values.producer?.trim());
  const isEditing = Boolean(initialValues?.id);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (canSaveMinimal) onSubmit(values);
  };

  return (
    <Paper
      component="form"
      onSubmit={handleSubmit}
      sx={{ p: 3 }}
      aria-label={isEditing ? t('common.bottle.edit') : t('common.bottle.add')}
    >
      <Typography variant="h6" fontWeight={700} gutterBottom>
        {isEditing ? t('common.bottle.edit') : t('common.bottle.add')}
      </Typography>

      {/* ÔöÇÔöÇ Step 1: Common trunk ÔöÇÔöÇ */}
      <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1.5 }}>
        {t('common.bottle.step1')}
      </Typography>

      <Grid container spacing={2}>
        {/* Category */}
        <Grid item xs={12} sm={4}>
          <FormControl fullWidth size="small" required>
            <InputLabel>{t('common.bottle.fields.category')}</InputLabel>
            <Select
              value={values.category ?? 'wine'}
              label={t('common.bottle.fields.category')}
              onChange={(e) => {
                setField('category', e.target.value as BottleCategory);
                setStep(2);
              }}
            >
              {(['wine', 'sparkling', 'spirit', 'cigar'] as BottleCategory[]).map((c) => (
                <MenuItem key={c} value={c}>{t(`common.categories.${c}`)}</MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        {/* Name */}
        <Grid item xs={12} sm={4}>
          <TextField
            fullWidth
            required
            label={t('common.bottle.fields.name')}
            value={values.name ?? ''}
            onChange={(e) => {
              setField('name', e.target.value);
              if (e.target.value && step === 1) setStep(2);
            }}
          />
        </Grid>

        {/* Producer */}
        <Grid item xs={12} sm={4}>
          <TextField
            fullWidth
            required
            label={t('common.bottle.fields.producer')}
            value={values.producer ?? ''}
            onChange={(e) => setField('producer', e.target.value)}
          />
        </Grid>
      </Grid>

      {/* Minimal save hint */}
      {canSaveMinimal && step === 1 && (
        <Box sx={{ mt: 2 }}>
          <Typography variant="caption" color="text.secondary">
            {t('common.bottle.saveMinimalHint')}
          </Typography>
        </Box>
      )}

      {/* ÔöÇÔöÇ Step 2: Category-specific essential fields ÔöÇÔöÇ */}
      {(step === 2 || isEditing) && values.category && (
        <>
          <Divider sx={{ my: 2.5 }} />
          <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1.5 }}>
            {t('common.bottle.step2')}
          </Typography>

          <CategoryFields
            category={values.category}
            values={values as Record<string, unknown>}
            onChange={setField}
            t={t}
          />

          {/* Optional fields toggle */}
          <Box sx={{ mt: 2 }}>
            <Tooltip title={showOptionals ? t('common.actions.showLess') : t('common.actions.showMore')}>
              <Button
                size="small"
                variant="text"
                onClick={() => setShowOptionals((prev) => !prev)}
                startIcon={showOptionals ? <ExpandLessIcon /> : <ExpandMoreIcon />}
                aria-expanded={showOptionals}
                aria-controls="optional-fields"
              >
                {showOptionals ? t('common.actions.showLess') : t('common.actions.showMore')}
              </Button>
            </Tooltip>
          </Box>

          <Collapse in={showOptionals}>
            <Box id="optional-fields" sx={{ mt: 2 }}>
              <OptionalFields
                category={values.category}
                values={values as Record<string, unknown>}
                onChange={setField}
                t={t}
              />
            </Box>
          </Collapse>
        </>
      )}

      {/* ÔöÇÔöÇ Actions ÔöÇÔöÇ */}
      <Box sx={{ mt: 3, display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
        <Button variant="outlined" onClick={onCancel} disabled={isSubmitting}>
          {t('common.actions.cancel')}
        </Button>
        <Button
          type="submit"
          variant="contained"
          startIcon={<SaveIcon />}
          disabled={!canSaveMinimal || isSubmitting}
          aria-label={isEditing ? t('common.actions.update') : t('common.bottle.saveMinimal')}
        >
          {isSubmitting
            ? t('common.status.saving')
            : isEditing
            ? t('common.actions.update')
            : t('common.bottle.saveMinimal')}
        </Button>
      </Box>
    </Paper>
  );
}

'use client';
import React from 'react';
import {
  Grid, TextField, Select, MenuItem, FormControl, InputLabel,
  FormControlLabel, Checkbox, Slider, Typography, Box,
} from '@mui/material';
import { BottleCategory } from '@/lib/bottles/types';

interface CategoryFieldsProps {
  category: BottleCategory;
  values: Record<string, unknown>;
  onChange: (field: string, value: unknown) => void;
  t: (key: string) => string;
}

/**
 * Champs essentiels affich├®s directement apr├¿s s├®lection de cat├®gorie.
 * Aucun champ essentiel n'est masqu├® (crit├¿re d'acceptation #2).
 */
export function CategoryFields({ category, values, onChange, t }: CategoryFieldsProps) {
  const field = (name: string, label: string, type: 'text' | 'number' = 'text', required = false) => (
    <Grid item xs={12} sm={6} key={name}>
      <TextField
        fullWidth
        required={required}
        label={label}
        type={type}
        value={String(values[name] ?? '')}
        onChange={(e) => onChange(name, type === 'number' ? (e.target.value ? Number(e.target.value) : undefined) : e.target.value)}
        inputProps={type === 'number' ? { min: 0, step: type === 'number' ? 1 : undefined } : undefined}
      />
    </Grid>
  );

  const vintageField = (
    <Grid item xs={12} sm={6} key="vintage">
      <TextField
        fullWidth
        label={t('common.bottle.fields.vintage')}
        type="number"
        value={String(values['vintage'] ?? '')}
        onChange={(e) => onChange('vintage', e.target.value ? Number(e.target.value) : undefined)}
        inputProps={{ min: 1800, max: new Date().getFullYear(), step: 1 }}
        helperText={t('common.bottle.fields.noVintage')}
      />
    </Grid>
  );

  switch (category) {
    case 'wine':
      return (
        <Grid container spacing={2}>
          {vintageField}
          <Grid item xs={12} sm={6}>
            <FormControl fullWidth size="small">
              <InputLabel>{t('common.bottle.fields.color')}</InputLabel>
              <Select
                value={String(values['color'] ?? '')}
                label={t('common.bottle.fields.color')}
                onChange={(e) => onChange('color', e.target.value)}
              >
                {['red', 'white', 'ros├®', 'orange'].map((c) => (
                  <MenuItem key={c} value={c}>{t(`common.bottle.color.${c}`)}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          {field('region', t('common.bottle.fields.region'))}
          {field('alcoholDegree', t('common.bottle.fields.alcoholDegree'), 'number')}
        </Grid>
      );

    case 'sparkling':
      return (
        <Grid container spacing={2}>
          {vintageField}
          <Grid item xs={12} sm={6}>
            <FormControl fullWidth size="small">
              <InputLabel>{t('common.bottle.fields.sparklingType')}</InputLabel>
              <Select
                value={String(values['sparklingType'] ?? '')}
                label={t('common.bottle.fields.sparklingType')}
                onChange={(e) => onChange('sparklingType', e.target.value)}
              >
                {['Champagne', 'Cr├®mant', 'Prosecco', 'Cava', 'P├®tillant Naturel', 'Autre'].map((s) => (
                  <MenuItem key={s} value={s}>{s}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          {field('sugarLevel', t('common.bottle.fields.sugarLevel'))}
        </Grid>
      );

    case 'spirit':
      return (
        <Grid container spacing={2}>
          {field('edition', t('common.bottle.fields.edition'))}
          {field('alcoholDegree', t('common.bottle.fields.alcoholDegree'), 'number', true)}
        </Grid>
      );

    case 'cigar':
      return (
        <Grid container spacing={2}>
          {field('format', t('common.bottle.fields.format'))}
          {field('quantity', t('common.bottle.fields.quantity'), 'number', true)}
        </Grid>
      );

    default:
      return null;
  }
}

// ÔöÇÔöÇÔöÇ Optional section ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

interface OptionalFieldsProps {
  category: BottleCategory;
  values: Record<string, unknown>;
  onChange: (field: string, value: unknown) => void;
  t: (key: string) => string;
}

/**
 * Champs optionnels regroup├®s dans une section repliable.
 * Visible uniquement si l'utilisateur clique "Afficher les compl├®ments".
 */
export function OptionalFields({ category, values, onChange, t }: OptionalFieldsProps) {
  const field = (name: string, label: string, type: 'text' | 'number' = 'text') => (
    <Grid item xs={12} sm={6} key={name}>
      <TextField
        fullWidth
        label={label}
        type={type}
        value={String(values[name] ?? '')}
        onChange={(e) => onChange(name, type === 'number' ? (e.target.value ? Number(e.target.value) : undefined) : e.target.value)}
      />
    </Grid>
  );

  const commonOptionals = (
    <>
      {field('location', t('common.bottle.fields.location'))}
      {field('collection', t('common.bottle.fields.collection'))}
      {field('purchasePrice', t('common.bottle.fields.purchasePrice'), 'number')}
      {field('estimatedValue', t('common.bottle.fields.estimatedValue'), 'number')}
      {field('photoUrl', t('common.bottle.fields.photoUrl'))}
      <Grid item xs={12} key="notes">
        <TextField
          fullWidth
          multiline
          rows={3}
          label={t('common.bottle.fields.notes')}
          value={String(values['notes'] ?? '')}
          onChange={(e) => onChange('notes', e.target.value)}
        />
      </Grid>
      <Grid item xs={12} sm={6} key="isOpened">
        <FormControlLabel
          control={
            <Checkbox
              checked={Boolean(values['isOpened'])}
              onChange={(e) => onChange('isOpened', e.target.checked)}
            />
          }
          label={t('common.bottle.fields.isOpened')}
        />
      </Grid>
      {Boolean(values['isOpened']) && (
        <Grid item xs={12} key="fillLevel">
          <Typography variant="body2" color="text.secondary" gutterBottom>
            {t('common.bottle.fields.fillLevel')} : {Number(values['fillLevel'] ?? 100)}%
          </Typography>
          <Slider
            value={Number(values['fillLevel'] ?? 100)}
            min={0}
            max={100}
            step={5}
            marks
            valueLabelDisplay="auto"
            onChange={(_e, v) => onChange('fillLevel', v)}
            aria-label={t('common.bottle.fields.fillLevel')}
          />
        </Grid>
      )}
    </>
  );

  const wineOptionals = (
    <>
      {field('bottleSize', t('common.bottle.fields.bottleSize'))}
      {field('peakMaturity', t('common.bottle.fields.peakMaturity'))}
      {field('serviceTemp', t('common.bottle.fields.serviceTemp'))}
      {field('lotNumber', t('common.bottle.fields.lotNumber'))}
      <Grid item xs={12} sm={6} key="needsAeration">
        <FormControlLabel
          control={
            <Checkbox
              checked={Boolean(values['needsAeration'])}
              onChange={(e) => onChange('needsAeration', e.target.checked)}
            />
          }
          label={t('common.bottle.fields.needsAeration')}
        />
      </Grid>
    </>
  );

  const sparklingOptionals = (
    <>
      {field('bottleSize', t('common.bottle.fields.bottleSize'))}
      {field('peakMaturity', t('common.bottle.fields.peakMaturity'))}
      {field('serviceTemp', t('common.bottle.fields.serviceTemp'))}
      {field('baseYear', t('common.bottle.fields.baseYear'), 'number')}
    </>
  );

  const spiritOptionals = (
    <>
      {field('declaredAge', t('common.bottle.fields.declaredAge'))}
      {field('caskType', t('common.bottle.fields.caskType'))}
      {field('aromaticProfile', t('common.bottle.fields.aromaticProfile'))}
      {field('additions', t('common.bottle.fields.additions'))}
      {field('lotNumber', t('common.bottle.fields.lotNumber'))}
      {field('bottleSize', t('common.bottle.fields.bottleSize'))}
    </>
  );

  const cigarOptionals = (
    <>
      {field('manufactureYear', t('common.bottle.fields.manufactureYear'), 'number')}
      {field('leafOrigin', t('common.bottle.fields.leafOrigin'))}
      {field('factoryCode', t('common.bottle.fields.factoryCode'))}
      {field('recommendedHumidity', t('common.bottle.fields.recommendedHumidity'), 'number')}
      {field('humidificationSystem', t('common.bottle.fields.humidificationSystem'))}
    </>
  );

  return (
    <Grid container spacing={2}>
      {commonOptionals}
      {category === 'wine' && wineOptionals}
      {category === 'sparkling' && sparklingOptionals}
      {category === 'spirit' && spiritOptionals}
      {category === 'cigar' && cigarOptionals}
    </Grid>
  );
}

'use client';
import React, { useEffect, useRef, useState } from 'react';
import { Alert, Box, Button, Collapse, LinearProgress, Typography } from '@mui/material';
import UndoIcon from '@mui/icons-material/Undo';

const UNDO_TIMEOUT_MS = 6000;

interface UndoToastProps {
  message: string;
  undoLabel: string;
  onUndo: () => void;
  onExpire: () => void;
}

/**
 * Toast non-bloquant avec compte-├á-rebours et bouton Undo.
 * Respecte les standards a11y : role="status", aria-live="polite".
 */
export function UndoToast({ message, undoLabel, onUndo, onExpire }: UndoToastProps) {
  const [progress, setProgress] = useState(100);
  const startTime = useRef(Date.now());
  const frameRef = useRef<number | undefined>(undefined);

  useEffect(() => {
    const animate = () => {
      const elapsed = Date.now() - startTime.current;
      const remaining = Math.max(0, 100 - (elapsed / UNDO_TIMEOUT_MS) * 100);
      setProgress(remaining);
      if (remaining > 0) {
        frameRef.current = requestAnimationFrame(animate);
      } else {
        onExpire();
      }
    };
    frameRef.current = requestAnimationFrame(animate);
    return () => {
      if (frameRef.current !== undefined) cancelAnimationFrame(frameRef.current);
    };
  }, [onExpire]);

  return (
    <Box
      role="status"
      aria-live="polite"
      sx={{
        position: 'fixed',
        bottom: 24,
        left: '50%',
        transform: 'translateX(-50%)',
        zIndex: 1400,
        minWidth: 320,
        maxWidth: 480,
      }}
    >
      <Alert
        severity="info"
        sx={{ boxShadow: 3, pr: 1 }}
        action={
          <Button
            size="small"
            startIcon={<UndoIcon />}
            onClick={onUndo}
            color="info"
            aria-label={undoLabel}
          >
            {undoLabel}
          </Button>
        }
      >
        <Typography variant="body2">{message}</Typography>
        <LinearProgress
          variant="determinate"
          value={progress}
          sx={{ mt: 1, borderRadius: 1, height: 3 }}
          color="info"
          aria-hidden="true"
        />
      </Alert>
    </Box>
  );
}
